{"path":"events.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Gatherings — Events | {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#0f1720;--card:#071021;--accent:#7CE7C6;--accent-2:#9B8CFF;--muted:#98A6B3;--glass:rgba(255,255,255,0.04);--glass-2:rgba(255,255,255,0.02);--radius:14px}
    html,body{height:100%;margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial; color:#e6f0f2;background:linear-gradient(180deg,#071021 0%, #04111b 60%);}
    .wrap{max-width:1100px;margin:32px auto;padding:28px}
    header{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px}
    .brand{display:flex;align-items:center;gap:14px}
    .logo{width:52px;height:52px;border-radius:10px;background:linear-gradient(135deg,var(--accent),var(--accent-2));display:grid;place-items:center;color:#05202c;font-weight:700;font-size:18px}
    nav{display:flex;gap:14px}
    nav a{color:#d8eef0;text-decoration:none;padding:8px 12px;border-radius:9px;font-weight:600}
    nav a:hover{background:rgba(255,255,255,0.03)}
    .hero{display:grid;grid-template-columns:1fr 380px;gap:26px;align-items:start;margin-top:6px}
    .hero-left{background:var(--glass);padding:28px;border-radius:var(--radius);backdrop-filter:blur(6px)}
    h1{margin:0;font-size:28px;letter-spacing:-0.02em;color:#f3fbfa}
    p.lead{color:var(--muted);margin-top:10px}
    .hero-cta{margin-top:18px}
    .btn{display:inline-block;padding:10px 16px;border-radius:10px;background:linear-gradient(90deg,var(--accent-2),var(--accent));color:#042328;font-weight:700;text-decoration:none}
    .side-card{background:linear-gradient(180deg,rgba(124,231,198,0.06),rgba(155,140,255,0.04));padding:18px;border-radius:12px;color:#e8fbf7}
    .next-title{font-size:13px;color:var(--muted);text-transform:uppercase;letter-spacing:1px}
    .next-name{font-size:18px;margin:6px 0 0}
    .meta{color:var(--muted);font-size:13px;margin-top:8px}
    .calendar{margin-top:22px;background:var(--glass-2);padding:14px;border-radius:12px}
    .evt{display:flex;gap:12px;padding:12px;border-radius:10px;align-items:center}
    .date{min-width:64px;background:#0a1920;padding:10px;border-radius:8px;text-align:center}
    .date b{display:block;color:var(--accent);font-size:20px}
    .evt-title{color:#e9fbfa}
    .evt-meta{color:var(--muted);font-size:13px}
    .disclaimer{margin-top:18px;font-size:13px;color:#cfe8e3;background:rgba(255,255,255,0.02);padding:12px;border-radius:10px}
    footer{margin-top:28px;color:var(--muted);font-size:13px;display:flex;justify-content:space-between;align-items:center}
    .pattern{position:fixed;right:10px;bottom:10px;opacity:0.12;width:360px;height:360px;background-image:url('assets/img/pattern.svg');background-size:cover;pointer-events:none}
    /* small responsive */
    @media (max-width:900px){.hero{grid-template-columns:1fr;}.pattern{display:none}}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div class="brand">
        <div class="logo">SND</div>
        <div>
          <div style="font-weight:800;color:#e6fbf6">{{BUSINESS_NAME}}</div>
          <div style="font-size:12px;color:var(--muted)">A refined listening practice in {{CITY}}, {{STATE}}</div>
        </div>
      </div>
      <nav>
        <a href="index.html">Gatherings</a>
        <a href="events.html" style="opacity:0.95">Calendar</a>
        <a href="private-sessions.html">Sanctuary</a>
        <a href="pricing.html">Value</a>
        <a href="about.html">Origin</a>
        <a href="book.html">Reserve</a>
      </nav>
    </header>

    <section class="hero">
      <div class="hero-left">
        <h1>Gathered Sound Evenings — live, held, and threaded</h1>
        <p class="lead">Join gentle collective sound sessions where layered tones guide us toward ease. Short form, warm presence, and clear intention—perfect for an evening pause.</p>
        <div class="hero-cta">
          <a class="btn" href="book.html">Save My Seat</a>
          <span style="margin-left:12px;color:var(--muted);font-weight:600">or call <a href="tel:{{PHONE}}" style="color:#dff8f0;text-decoration:none">{{PHONE}}</a></span>
        </div>
        <div class="disclaimer" style="margin-top:18px">
          Contraindications: Not recommended during pregnancy without healthcare guidance, for people with uncontrolled epilepsy, implanted medical devices, or conditions sensitive to sustained sound/vibration. Contact <a href="mailto:{{EMAIL}}" style="color:#dff8f0">{{EMAIL}}</a> for specifics.
        </div>
      </div>

      <aside class="side-card">
        <div class="next-title">Next Event</div>
        <div id="nextEvent" style="margin-top:8px">
          <div class="next-name">— Finding Stillness: Evening Sound Weave</div>
          <div class="meta">Fri • Feb 20 • 7:00–8:00pm • The Violet Room</div>
          <div style="margin-top:12px;display:flex;gap:8px">
            <a class="btn" href="book.html">Reserve Ticket</a>
            <a href="#calendar" style="color:#d8f3ef;padding:8px 10px;border-radius:8px;background:transparent;border:1px solid rgba(255,255,255,0.03);text-decoration:none">See Calendar</a>
          </div>
        </div>
        <div style="margin-top:14px;color:var(--muted);font-size:13px">Capacity limited • Soft blankets provided • Arrive 10 min early</div>
      </aside>
    </section>

    <section id="calendar" style="margin-top:20px">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <h3 style="margin:0;color:#e8fbf9">Upcoming Gatherings</h3>
        <div style="color:var(--muted);font-size:13px">Tickets $25–45 • Sliding scale available</div>
      </div>
      <div class="calendar" style="margin-top:12px">
        <div class="evt" data-date="2026-02-20">
          <div class="date"><b>20</b><div style="font-size:11px;color:var(--muted)">Feb</div></div>
          <div>
            <div class="evt-title">Finding Stillness: Evening Sound Weave</div>
            <div class="evt-meta">Fri • 7:00–8:00pm • The Violet Room • $30</div>
          </div>
        </div>
        <div class="evt" data-date="2026-02-27">
          <div class="date"><b>27</b><div style="font-size:11px;color:var(--muted)">Feb</div></div>
          <div>
            <div class="evt-title">Studio Resonance — layered bowls & chimes</div>
            <div class="evt-meta">Sat • 5:30–6:30pm • Studio A • $35</div>
          </div>
        </div>
        <div class="evt" data-date="2026-03-06">
          <div class="date"><b>6</b><div style="font-size:11px;color:var(--muted)">Mar</div></div>
          <div>
            <div class="evt-title">Dusk Drift — sound with breath-guides</div>
            <div class="evt-meta">Fri • 6:30–7:30pm • The Violet Room • $25</div>
          </div>
        </div>
      </div>
    </section>

    <section style="margin-top:22px;display:flex;gap:18px;align-items:flex-start">
      <div style="flex:1;background:linear-gradient(180deg,rgba(124,231,198,0.02),transparent);padding:18px;border-radius:12px">
        <h4 style="margin:0 0 8px;color:#e8fbf9">How we hold an evening</h4>
        <p style="color:var(--muted);margin:0">We open with a short orientation, move through layered sound maps, and finish with a soft return and tea. Sessions are intentionally simple—designed to reduce cognitive load and deepen listening.</p>
      </div>
      <div style="width:320px;background:var(--glass);padding:14px;border-radius:12px">
        <h4 style="margin:0 0 10px;color:#e8fbf9">Accessibility & arrival</h4>
        <p style="margin:0;color:var(--muted);font-size:14px">Limited floor seating; alternative chairs available. If you need assistance on arrival, call <a href="tel:{{PHONE}}" style="color:#dff8f0">{{PHONE}}</a>.</p>
      </div>
    </section>

    <footer>
      <div>&copy; <strong>{{BUSINESS_NAME}}</strong> • Events in {{CITY}}, {{STATE}}</div>
      <div style="color:var(--muted)">Questions? <a href="mailto:{{EMAIL}}" style="color:#dff8f0">{{EMAIL}}</a></div>
    </footer>
  </div>
  <div class="pattern"></div>

  <script>
    // Choose the next event (first upcoming) and render into nextEvent
    (function(){
      const now = new Date();
      const items = Array.from(document.querySelectorAll('.evt')).map(el=>({el, date:new Date(el.getAttribute('data-date'))}));
      items.sort((a,b)=>a.date-b.date);
      const next = items.find(i=>i.date>=now) || items[0];
      if(next){
        const title = next.el.querySelector('.evt-title').textContent.trim();
        const meta = next.el.querySelector('.evt-meta').textContent.trim();
        document.getElementById('nextEvent').querySelector('.next-name').textContent = title;
        document.getElementById('nextEvent').querySelector('.meta').textContent = meta;
      }
    })();
  </script>
</body>
</html>"} 
{"path":"private-sessions.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Sanctuary — Private Sessions | {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#08121a;--card:#07121a;--accent:#FFD27A;--calm:#7CE7C6;--muted:#9FB3BA}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;background:linear-gradient(180deg,#041018,#071422);color:#eaf7f4}
    .site{max-width:980px;margin:28px auto;padding:22px}
    header{display:flex;align-items:center;justify-content:space-between}
    .logo{font-weight:900;background:linear-gradient(90deg,var(--accent),var(--calm));-webkit-background-clip:text;background-clip:text;color:transparent;font-size:20px}
    nav a{color:#cfeef0;text-decoration:none;margin-left:14px;font-weight:700}
    .hero{margin-top:18px;padding:22px;background:rgba(255,255,255,0.02);border-radius:16px;display:flex;gap:20px}
    .hero .left{flex:1}
    h1{margin:0;font-size:24px}
    p.lead{color:var(--muted);margin-top:8px}
    .book-cta{margin-top:14px}
    .btn{padding:10px 14px;border-radius:10px;background:linear-gradient(90deg,var(--accent),var(--calm));color:#042328;font-weight:800;text-decoration:none}
    .side{width:320px;background:rgba(255,255,255,0.02);padding:14px;border-radius:12px}
    .session-list{display:flex;flex-direction:column;gap:10px;margin-top:18px}
    .session{background:rgba(255,255,255,0.01);padding:12px;border-radius:10px}
    .price{font-weight:900;color:var(--accent);font-size:18px}
    .micro-compare{display:flex;gap:10px;align-items:center;margin-top:14px}
    .toggle{background:#06202a;padding:6px;border-radius:999px;display:inline-flex}
    .toggle button{background:transparent;border:0;color:var(--muted);padding:6px 10px;border-radius:999px;font-weight:700}
    .toggle button.active{background:linear-gradient(90deg,var(--accent),var(--calm));color:#042328}
    .proof{margin-top:18px;background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent);padding:14px;border-radius:12px}
    .testi{min-height:80px;display:flex;gap:12px;align-items:center}
    .avatar{width:56px;height:56px;border-radius:10px;background:linear-gradient(180deg,#124857,#082b2b);display:grid;place-items:center;font-weight:800}
    .quote{color:var(--muted)}
    .badges{display:flex;gap:8px;margin-top:10px}
    .badge{background:#061c21;padding:8px 10px;border-radius:8px;cursor:pointer;color:#bfece6;font-size:13px}
    .tooltip{position:absolute;background:#042128;padding:8px;border-radius:8px;color:#d7faf3;font-size:13px;box-shadow:0 6px 18px rgba(2,8,10,0.6)}
    .disclaimer{margin-top:12px;color:#cfe8e3;font-size:13px}
  </style>
</head>
<body>
  <div class="site">
    <header>
      <div style="display:flex;align-items:center;gap:12px">
        <div class="logo">{{BUSINESS_NAME}}</div>
        <div style="color:var(--muted);font-size:13px">Private sound work • one-to-one & small duets</div>
      </div>
      <nav>
        <a href="index.html">Gatherings</a>
        <a href="events.html">Calendar</a>
        <a href="private-sessions.html">Sanctuary</a>
        <a href="pricing.html">Value</a>
        <a href="contact.html">Connect</a>
      </nav>
    </header>

    <section class="hero">
      <div class="left">
        <h1>Private sound sessions — tailored listening</h1>
        <p class="lead">Quietly tailored, carefully timed sessions for nervous-system regulation, personal recalibration, or guided rest. Choose a single session or a phased package for deeper work.</p>

        <div class="micro-compare" aria-hidden>
          <div style="font-size:13px;color:var(--muted);font-weight:700">View pricing:</div>
          <div class="toggle" id="toggleSessions">
            <button data-mode="single" class="active">Single</button>
            <button data-mode="pack">Package</button>
          </div>
          <div style="margin-left:auto;font-weight:900;color:var(--accent)" id="livePrice">$120</div>
        </div>

        <div style="margin-top:12px">
          <a class="btn" href="book.html">Begin Private Booking</a>
        </div>

        <div class="disclaimer">Contraindications: Private sessions involve sustained tones and subtle vibration. Not advised for those with pacemakers, implanted devices, or uncontrolled seizure disorders. If pregnant or under medical care, consult a provider first.</div>

        <div class="proof" id="proof">
          <div style="display:flex;justify-content:space-between;align-items:center">
            <strong>Proof Gallery</strong>
            <div style="font-size:13px;color:var(--muted)">Real reflections & third-party cred</div>
          </div>
          <div class="testi" id="testiArea">
            <div class="avatar">JM</div>
            <div>
              <div style="font-weight:800;color:#e8fbf9" id="testiName">—</div>
              <div class="quote" id="testiText">—</div>
            </div>
          </div>
          <div class="badges" id="badges">
            <div class="badge" data-tip="Featured: City Wellness Review">City Wellness</div>
            <div class="badge" data-tip="Guest workshop at Blue Lotus Studio">Blue Lotus</div>
            <div class="badge" data-tip="Endorsed by a local therapist collective">Therapist Collective</div>
          </div>
        </div>
      </div>

      <aside class="side">
        <h4 style="margin:0 0 8px">Session types</h4>
        <div class="session-list">
          <div class="session">
            <div style="display:flex;justify-content:space-between"><div>Guided Sound Session</div><div class="price">$120</div></div>
            <div style="color:var(--muted);font-size:13px;margin-top:6px">45–60 min • focused restorative work</div>
          </div>
          <div class="session">
            <div style="display:flex;justify-content:space-between"><div>Pairing Session</div><div class="price">$180</div></div>
            <div style="color:var(--muted);font-size:13px;margin-top:6px">For two people • shared recalibration</div>
          </div>
        </div>
        <hr style="border:none;border-top:1px solid rgba(255,255,255,0.02);margin:12px 0">
        <div style="font-size:13px;color:var(--muted)">Sessions by appointment. Gift certificates available. Call <a href="tel:{{PHONE}}" style="color:#dff8f0">{{PHONE}}</a>.</div>
      </aside>
    </section>

    <footer style="margin-top:18px;color:var(--muted);font-size:13px;display:flex;justify-content:space-between">
      <div>&copy; {{BUSINESS_NAME}}</div>
      <div>Email: <a href="mailto:{{EMAIL}}" style="color:#dff8f0">{{EMAIL}}</a></div>
    </footer>
  </div>

  <script>
    // Micro pricing toggle with animated numbers
    (function(){
      const toggle = document.getElementById('toggleSessions');
      const btns = toggle.querySelectorAll('button');
      const livePrice = document.getElementById('livePrice');
      const pricing = {single:120, pack:520}; // pack is 5-session package effective price
      let current = 'single';

      function animateValue(el, start, end, duration){
        const range = end - start; let startTime = null;
        function step(ts){
          if(!startTime) startTime = ts;
          const progress = Math.min((ts - startTime)/duration,1);
          const value = Math.round(start + range*progress);
          el.textContent = '$' + value;
          if(progress<1) requestAnimationFrame(step);
        }
        requestAnimationFrame(step);
      }

      btns.forEach(b=>b.addEventListener('click', ()=>{
        btns.forEach(x=>x.classList.remove('active'));
        b.classList.add('active');
        const mode = b.getAttribute('data-mode');
        const from = parseInt(livePrice.textContent.replace(/[^0-9]/g,''))||0;
        const to = pricing[mode];
        animateValue(livePrice, from, to, 420);
        current = mode;
      }));

      // initial value
      livePrice.textContent = '$' + pricing[current];
    })();

    // Proof Gallery rotating testimonials and badge tooltips
    (function(){
      const testimonials = [
        {name:'Marin K', text:'A gentle, unmistakable settling — quiet but powerful. I slept deeply the next two nights.'},
        {name:'A. Rivera', text:'The session supported a long week of travel. I left with calmer shoulders and clearer thinking.'},
        {name:'S. Patel', text:'Precise listening, generous holding. Felt seen by sound that never shouted.'}
      ];
      let idx=0; const nameEl = document.getElementById('testiName');
      const textEl = document.getElementById('testiText');
      function show(i){
        const t = testimonials[i%testimonials.length];
        nameEl.textContent = t.name;
        textEl.textContent = t.text;
      }
      show(0);
      setInterval(()=>{idx=(idx+1)%testimonials.length;show(idx);},4200);

      // badges tooltip
      const badges = document.getElementById('badges');
      let tipEl;
      badges.addEventListener('mouseover', e=>{
        const b = e.target.closest('.badge'); if(!b) return;
        const tip = b.getAttribute('data-tip');
        tipEl = document.createElement('div');
        tipEl.className = 'tooltip'; tipEl.textContent = tip; document.body.appendChild(tipEl);
        const r = b.getBoundingClientRect(); tipEl.style.left = (r.left + window.scrollX + r.width/2 - tipEl.offsetWidth/2) + 'px';
        tipEl.style.top = (r.top + window.scrollY - 10 - tipEl.offsetHeight) + 'px';
      });
      badges.addEventListener('mouseout', e=>{ if(tipEl){tipEl.remove(); tipEl = null;} });
    })();
  </script>
</body>
</html>"} 
{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Value — Pricing | {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071423;--card:#081826;--gold:#FFD27A;--mint:#7CE7C6;--muted:#9db0b6}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;background:linear-gradient(180deg,#041018,#07202a);color:#eaf7f4}
    .container{max-width:1000px;margin:28px auto;padding:22px}
    header{display:flex;justify-content:space-between;align-items:center}
    header a{color:#cfeef0;text-decoration:none;margin-left:14px;font-weight:700}
    .intro{display:flex;gap:20px;align-items:center;margin-top:14px}
    .intro h1{margin:0;font-size:26px}
    .card{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:18px;border-radius:12px;margin-top:16px}
    .plans{display:flex;gap:12px;margin-top:12px}
    .plan{flex:1;padding:16px;border-radius:12px;background:rgba(255,255,255,0.01);text-align:center}
    .plan h3{margin:6px 0 10px}
    .cost{font-size:28px;font-weight:900;color:var(--gold)}
    .muted{color:var(--muted)}
    .toggle-row{display:flex;gap:12px;align-items:center;justify-content:center;margin-top:10px}
    .switch{background:#06262a;padding:4px;border-radius:999px;display:inline-flex}
    .switch button{background:transparent;border:0;color:var(--muted);padding:8px 12px;border-radius:999px;font-weight:800}
    .switch button.active{background:linear-gradient(90deg,var(--gold),var(--mint));color:#042328}
    .cta{margin-top:12px;text-align:center}
    .btn{padding:10px 14px;border-radius:10px;background:linear-gradient(90deg,var(--gold),var(--mint));color:#042328;font-weight:800;text-decoration:none}
    .fine{color:var(--muted);font-size:13px;margin-top:10px}
  </style>
</head>
<body>
  <div class="container">
    <header>
      <div style="font-weight:900;color:#eafbf6">{{BUSINESS_NAME}}</div>
      <nav>
        <a href="index.html">Gatherings</a>
        <a href="events.html">Calendar</a>
        <a href="private-sessions.html">Sanctuary</a>
        <a href="pricing.html">Value</a>
        <a href="contact.html">Connect</a>
      </nav>
    </header>

    <div class="intro">
      <div style="flex:1">
        <h1>Transparent access — session and package pricing</h1>
        <div class="muted">Simple tiers—pay per visit or choose a package for deeper rhythm.</div>
      </div>
      <div style="width:260px;text-align:right">
        <div style="font-size:13px;color:var(--muted)">Questions? <a href="mailto:{{EMAIL}}" style="color:#dff8f0">{{EMAIL}}</a></div>
        <div style="margin-top:8px;color:var(--muted)">Phone: <a href="tel:{{PHONE}}" style="color:#dff8f0">{{PHONE}}</a></div>
      </div>
    </div>

    <div class="card">
      <div style="text-align:center;font-weight:800">Choose view</div>
      <div class="toggle-row">
        <div class="switch" id="planSwitch">
          <button data-view="per" class="active">Per Session</button>
          <button data-view="package">Package</button>
        </div>
      </div>

      <div class="plans" id="plansArea">
        <div class="plan">
          <h3>Intro Session</h3>
          <div class="cost" data-base="95">$95</div>
          <div class="muted">60 min • single intake & session</div>
        </div>
        <div class="plan">
          <h3>Focused Visit</h3>
          <div class="cost" data-base="120">$120</div>
          <div class="muted">45–60 min • targeted work</div>
        </div>
        <div class="plan">
          <h3>Deep Cycle (5)</h3>
          <div class="cost" data-base="520">$520</div>
          <div class="muted">Five-session package — sustained change</div>
        </div>
      </div>

      <div class="cta">
        <a class="btn" href="book.html">Choose and Reserve</a>
        <div class="fine">Packages are redeemable over 6 months. Discounts applied on packages below.</div>
      </div>
    </div>

    <div style="margin-top:18px;color:var(--muted);font-size:13px">
