    </div>

    <footer style="margin-top:26px;color:var(--muted);font-size:13px">© {{BUSINESS_NAME}} • Serving {{CITY}}, {{STATE}}</footer>
  </div>

  <script>
    // Pricing comparator with animated numbers
    (function(){
      const switchEl = document.getElementById('planSwitch');
      const buttons = switchEl.querySelectorAll('button');
      const costs = document.querySelectorAll('.cost');

      const perPrices = [95,120,520];
      const packagePrices = [80,110,460]; // when switched to package view show per-session-equivalent or savings

      function animate(el, start, end, ms){
        const range = end - start; let startTime=null;
        function step(ts){
          if(!startTime) startTime=ts;
          const progress = Math.min((ts-startTime)/ms,1);
          const val = Math.round(start + range*progress);
          el.textContent = '$' + val;
          if(progress<1) requestAnimationFrame(step);
        }
        requestAnimationFrame(step);
      }

      buttons.forEach(btn=>btn.addEventListener('click', ()=>{
        buttons.forEach(b=>b.classList.remove('active'));
        btn.classList.add('active');
        const view = btn.getAttribute('data-view');
        if(view==='per'){
          costs.forEach((c,i)=>{ const from = parseInt(c.textContent.replace(/[^0-9]/g,''))||0; animate(c,from,perPrices[i],420);} );
        } else {
          costs.forEach((c,i)=>{ const from = parseInt(c.textContent.replace(/[^0-9]/g,''))||0; animate(c,from,packagePrices[i],420);} );
        }
      }));

      // set initial values
      costs.forEach((c,i)=>{ c.textContent = '$' + perPrices[i]; });
    })();
  </script>
